// WSK-29 -- the gate, same doctrine wd-zoneb-intake.json's own 'Gate + build MCP call' node uses
// (that ticket's own comment: 'inert until explicitly enabled ... enabling this flag before those
// land means every call 403s at the hub, which is the correct fail-closed outcome, not a workflow
// bug'). This flow adds a SECOND, stronger reason to stay gated: unlike that ticket, the tool this
// flow calls (webdev.listPendingContractNotices) does not exist ANYWHERE in this repo yet -- there
// is no ticket number to point at for 'lands with #N', because none has been scoped. Flip
// WD_CONTRACT_WATCH_ENABLED=1 only once that tool is registered AND the wf:wd-contract-watch
// automation-policy.ts entry (already pre-added, see this workflow's meta.description) resolves to
// a real tool name instead of a 404.
if ($env.WD_CONTRACT_WATCH_ENABLED !== '1') {
  throw new Error('wd-contract-watch: disabled (WD_CONTRACT_WATCH_ENABLED != 1) -- gated until webdev.listPendingContractNotices is registered (platform-nest webdev module); see this workflow node\'s own comment for the contract it expects');
}
return [{ json: {} }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'webdev.listPendingContractNotices error');
const rows = JSON.parse(rpc.result?.content?.[0]?.text ?? '[]');
const notices = (Array.isArray(rows) ? rows : []).filter((r) => r && r.recipientId);
if (notices.length === 0) return []; // nothing to notify -> stop (a stale pin with no recipient still exists; this flow just raises no notice for it)
return notices.map((n) => ({ json: n }));

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'notify failed');
return [{ json: { ok: true } }];
